INSERT INTO products (slug, name, description, cover_image_url, product_type_id, platform_id) VALUES
    ('other-minecraft-java-bedrock-edition-pc-official-website-key-global', 'Minecraft: Java & Bedrock Edition (PC) Official website Key GLOBAL', 'Dig into Minecraft on PC with both Java Edition and Bedrock Edition in one bundle. Build in Creative mode or gather resources and face hostile mobs in Survival.

Java Edition is the choice for Java servers and mods, while Bedrock Edition lets you join friends on compatible Bedrock devices. Choose the edition that matches the world you want to play in.', '/uploads/products/other-minecraft-java-bedrock-edition-pc-official-website-key-global.png', 1, 12),
    ('kaspersky-premium-2-years-10-devices-key-europe', 'Kaspersky Premium (2 Years / 10 Devices) Key EUROPE', 'Kaspersky Premium provides two years of security for up to ten devices. It suits households that want to manage protection for several computers and phones under one subscription.

Use it to protect everyday activities such as browsing, shopping and opening downloads. Check the supported operating systems and the European activation region before assigning devices.', '/uploads/products/kaspersky-premium-2-years-10-devices-key-europe.jpg', 7, 28),
    ('xbox-minecraft-xbox-one-xbox-series-x-s-xbox-live-key-global', 'Minecraft (Xbox One/Xbox Series X|S) Xbox Live Key GLOBAL', 'Explore procedurally generated Minecraft worlds on Xbox One or Xbox Series X and S. Gather materials, build a shelter and turn it into a base, or start in Creative mode with unlimited blocks.

This is the Xbox edition of Minecraft. It runs on the supported Xbox consoles listed in the title and uses your Xbox account for activation.', '/uploads/products/xbox-minecraft-xbox-one-xbox-series-x-s-xbox-live-key-global.jpg', 1, 2),
    ('roblox-roblox-100-robux-key-global', 'Roblox - 100 Robux Key GLOBAL', 'Add 100 Robux to a Roblox account with this digital code. Robux can be spent on eligible avatar accessories or items sold inside participating experiences.

Redeem it on the account that should receive the balance. The code adds virtual currency and does not unlock a specific Roblox experience or item.', '/uploads/products/roblox-roblox-100-robux-key-global.jpg', 5, 13),
    ('recharge-orange-top-up-poland', 'Recharge Orange - top up Poland', 'Add prepaid credit to an eligible Orange Poland mobile number. A recharge can be used by the recipient under the terms of their current prepaid tariff.

Check that the number belongs to Orange Poland before submitting it. This recharge is intended for an existing prepaid line, rather than a new SIM or a monthly contract.', '/uploads/products/recharge-orange-top-up-poland.jpg', 9, 250),
    ('other-call-of-duty-modern-warfare-4-monster-energy-full-set-pack-dlc-ps4-ps5-xbox-one-xbox-series-x-pc-official-website-key-global', 'Call of Duty: Modern Warfare 4 Monster Energy Full Set Pack (DLC) (PS4/PS5/XBOX ONE/XBOX SERIES X/PC) Official Website Key GLOBAL', 'This Modern Warfare 4 add-on contains the Monster Energy Full Set Pack promotional content. It is meant for players who want to add the branded set to their Call of Duty account.

The pack does not include the base game. Check the redemption instructions for your supported console or PC and use the account linked to your game.', '/uploads/products/other-call-of-duty-modern-warfare-4-monster-energy-full-set-pack-dlc-ps4-ps5-xbox-one-xbox-series-x-pc-official-website-key-global.png', 2, 4),
    ('transcash-transcash-50-eur-voucher-lithuania', 'Transcash 50 EUR Voucher LITHUANIA', 'This Transcash voucher has a face value of €50 and is listed for Lithuania. It supplies a prepaid code for use through the compatible Transcash service.

Check the eligibility and redemption conditions of the receiving account before entering the code. Use only Transcash channels to redeem the voucher.', '/uploads/products/transcash-transcash-50-eur-voucher-lithuania.jpg', 6, 133),
    ('steam-gift-card-steam-wallet-gift-card-20-eur-steam-key-lithuania', 'Steam Wallet Gift Card 20 EUR Steam Key LITHUANIA', 'Add €20 to a Steam Wallet eligible for Lithuanian redemption. Wallet funds can be used for eligible games, downloadable content and other Steam purchases.

Redeem the code on your own Steam account and check its store country before purchase. The card adds wallet credit rather than granting a particular game.', '/uploads/products/steam-gift-card-steam-wallet-gift-card-20-eur-steam-key-lithuania.jpg', 4, 8),
    ('razer-razer-gold-gift-card-2-usd-key-global', 'Razer Gold Gift Card 2 USD Key GLOBAL', 'Add US$2 of Razer Gold to an eligible wallet. It is a small denomination for topping up an existing balance or making a low-cost purchase with a participating partner.

Check the currency supported by your Razer Gold account. Availability of items and services depends on the partner where you spend the credit.', '/uploads/products/razer-razer-gold-gift-card-2-usd-key-global.jpg', 3, 21),
    ('airalo-airalo-esim-50-usd-voucher-global', 'Airalo eSIM 50 USD Voucher GLOBAL', 'This US$50 Airalo voucher provides credit toward an eligible travel eSIM purchase. Choose a destination plan based on how much mobile data you need and how long you will travel.

The voucher is separate from the eSIM itself. Confirm that your phone supports eSIM and is carrier-unlocked before choosing a plan.', '/uploads/products/airalo-airalo-esim-50-usd-voucher-global.jpg', 11, 301),
    ('steam-football-manager-27-steam-key-pc-europe', 'Football Manager 27 Steam Key (PC) EUROPE', 'Football Manager 27 puts you in charge of a football club on PC. Build a squad, choose tactics and make decisions about recruitment and development across a season.

This Steam key is listed for Europe. Use a compatible Steam account and check the product availability and system requirements before planning your first season.', '/uploads/products/steam-football-manager-27-steam-key-pc-europe.jpg', 1, 1),
    ('windows-store-minecraft-java-bedrock-edition-pc-windows-store-key-global', 'Minecraft: Java & Bedrock Edition (PC) Windows Store Key GLOBAL', 'Get the PC bundle of Minecraft Java and Bedrock Edition through the Windows Store. The two editions share the block-building sandbox but serve different communities and multiplayer setups.

Redeem on the Microsoft account you plan to play with. Use Java Edition for compatible Java servers and mods, or Bedrock Edition to play with friends on supported Bedrock devices.', '/uploads/products/windows-store-minecraft-java-bedrock-edition-pc-windows-store-key-global.png', 1, 12),
    ('wondershare-wondershare-filmora-15-video-editor-1-device-lifetime-wondershare-key-mac-global', 'Wondershare Filmora 15 Video Editor (1 Device, Lifetime) Wondershare Key (MAC) GLOBAL', 'Filmora 15 for Mac is a video editor for assembling clips, adding text and working with audio on a timeline. It suits projects such as tutorials, family videos and social clips.

This listing covers a lifetime license for one Mac. Check Filmora''s terms for version upgrades and optional assets before choosing it for a longer project.', '/uploads/products/wondershare-wondershare-filmora-15-video-editor-1-device-lifetime-wondershare-key-mac-global.png', 7, 97),
    ('paysafecard-paysafecard-25-eur-voucher-lithuania', 'PaysafeCard Classic 25 EUR Voucher LITHUANIA', 'PaysafeCard Classic with a €25 face value offers a prepaid way to pay at supported online merchants. The code represents a fixed amount rather than a subscription.

This voucher is listed for Lithuania. Confirm that the merchant accepts PaysafeCard and that your country and account meet the redemption requirements.', '/uploads/products/paysafecard-paysafecard-25-eur-voucher-lithuania.png', 6, 46),
    ('recharge-pildyk-top-up-lithuania', 'Recharge Pildyk - top up Lithuania', 'Recharge an eligible Lithuanian Pildyk prepaid number. The recipient can use the added balance according to the conditions of their current prepaid plan.

Verify the phone number and network before submitting the top-up. The recharge applies to an existing Pildyk service.', '/uploads/products/recharge-pildyk-top-up-lithuania.jpg', 9, 302),
    ('psn-fortnite-neo-versa-bundle-500-v-bucks-ps4-psn-key-europe', 'Fortnite: Neo Versa Bundle + 500 V-Bucks (PS4) PSN Key EUROPE', 'The Neo Versa bundle adds Fortnite cosmetic content together with 500 V-Bucks. The cosmetics and the currency are offered together in this PlayStation bundle.

This PS4 listing uses a European PlayStation Network key. Check the country of your PSN account and use the account connected to your Fortnite profile.', '/uploads/products/psn-fortnite-neo-versa-bundle-500-v-bucks-ps4-psn-key-europe.jpg', 2, 5),
    ('steam-gift-project-zomboid-steam-gift-global', 'Project Zomboid Steam Gift GLOBAL', 'Project Zomboid is an isometric zombie survival game built around scavenging, injuries and resource management. A secured building buys time, but water, food and noise can determine how long you survive.

This listing is delivered as a Steam Gift. Check the gift requirements before accepting it on the Steam account where you want to play.', '/uploads/products/steam-gift-project-zomboid-steam-gift-global.jpg', 1, 43),
    ('other-netflix-gift-card-50-eur-key-europe', 'Netflix Gift Card 50 EUR Key EUROPE', 'This €50 Netflix gift card adds credit to an eligible Netflix membership. The credit can go toward the cost of streaming under your current or newly selected plan.

This is a European listing. Check the gift card currency and the billing country required by Netflix before applying the code.', '/uploads/products/other-netflix-gift-card-50-eur-key-europe.jpg', 3, 49),
    ('novyro-novyro-esim-20gb-30-day-33-countries-key-europe', 'Novyro eSIM 20GB 30-Day 33 Countries Key EUROPE', 'This Novyro travel eSIM provides 20 GB for up to 30 days across the plan''s listed 33 countries. It is suited to trips where you expect to use maps, messaging and mobile data regularly.

Check that the destinations on your itinerary are covered and that your device supports eSIM. Review the activation instructions before departing.', '/uploads/products/novyro-novyro-esim-20gb-30-day-33-countries-key-europe.png', 11, 249),
    ('fortnite-fortnite-1000-v-bucks-gift-card-key-global', 'Fortnite - 1000 V-Bucks Gift Card Key GLOBAL', 'Add 1,000 V-Bucks to an eligible Fortnite account. The currency can be used on items such as outfits and emotes when they are available in the in-game shop.

The card adds currency only. Check the redemption method for your account and platform before purchase.', '/uploads/products/fortnite-fortnite-1000-v-bucks-gift-card-key-global.jpg', 5, 65),
    ('eneba-eneba-gift-card-10-eur-global', 'Eneba Gift Card 10 EUR GLOBAL', 'This Eneba gift card provides €10 in credit for eligible purchases on Eneba. It gives the recipient a balance they can use to choose their own product.

Check Eneba''s gift card conditions before redemption, including any exclusions that apply to payment with gift card credit.', '/uploads/products/eneba-eneba-gift-card-10-eur-global.png', 4, 288),
    ('flexepin-flexepin-100-eur-voucher-lithuania', 'Flexepin 100 EUR Voucher LITHUANIA', 'This €100 Flexepin voucher provides prepaid credit for services that accept Flexepin. Enter the voucher code only at a participating merchant you intend to pay.

The voucher is listed for Lithuania. Check merchant acceptance and any country restrictions before redeeming the code.', '/uploads/products/flexepin-flexepin-100-eur-voucher-lithuania.jpg', 6, 38),
    ('riot-games-valorant-gift-card-2575-valorant-points-europe', 'Valorant Points 2575 VP Key - EUROPE', 'Add 2,575 Valorant Points to an eligible European VALORANT account. VP can be used for available in-game purchases such as weapon cosmetics and passes.

Confirm the region of your Riot account before redeeming. This key adds points and does not include a specific skin or bundle.', '/uploads/products/riot-games-valorant-gift-card-2575-valorant-points-europe.jpg', 5, 7),
    ('other-norton-360-premium-75gb-10-devices-1-year-norton-key-europe', 'Norton 360 Premium 75GB - 10 Devices 1 Year - Norton Key EUROPE', 'Norton 360 Premium provides one year of protection for up to ten supported devices. The package includes a 75 GB cloud backup allowance where that feature is supported.

Check the European activation region and which features work on your operating systems. Device coverage does not make desktop features available on every mobile platform.', '/uploads/products/other-norton-360-premium-75gb-10-devices-1-year-norton-key-europe.jpg', 7, 57),
    ('other-call-of-duty-r-modern-warfare-r-ii-burger-king-operator-skin-1-hour-2xp-dlc-www-callofduty-com-key-global', 'Call of Duty®: Modern Warfare® II  -  Burger King Operator Skin + 1 Hour 2XP (DLC) www.callofduty.com Key GLOBAL', 'This Modern Warfare II promotion includes the Burger King Operator Skin and one hour of Double XP. It pairs a cosmetic reward with a temporary progression bonus.

Redeem through the instructions for the Call of Duty account you use to play. The add-on requires the base game and does not grant a copy of it.', '/uploads/products/other-call-of-duty-r-modern-warfare-r-ii-burger-king-operator-skin-1-hour-2xp-dlc-www-callofduty-com-key-global.jpg', 2, 83),
    ('gigsky-gigsky-gift-card-10-eur-key-global', 'GigSky Gift Card 10 EUR Key GLOBAL', 'This GigSky gift card has a value of €10 for eligible GigSky purchases. You can put the credit toward mobile data for a trip after choosing a destination plan.

Check redemption eligibility and confirm that your phone supports eSIM. The card balance does not select or activate a travel plan on its own.', '/uploads/products/gigsky-gigsky-gift-card-10-eur-key-global.jpg', 11, 303),
    ('f-secure-internet-f-secure-total-protection-3-devices-2-years-key-europe', 'F-Secure Total Protection 3 Devices 2 Years Key EUROPE', 'F-Secure Total provides security coverage for up to three devices for two years. It is intended for users who want to manage protection across several supported devices with one license.

Check the European activation region and the features available on each operating system before installing.', '/uploads/products/f-secure-internet-f-secure-total-protection-3-devices-2-years-key-europe.jpg', 7, 103),
    ('other-roblox-doggy-backpack-mining-simulator-2-dlc-official-website-key-global', 'ROBLOX Doggy Backpack - Mining Simulator 2 (DLC) Official Website Key GLOBAL', 'The Doggy Backpack is digital add-on content for Mining Simulator 2 on Roblox. It is intended for a player who wants the named backpack in that experience.

Redeem the key through the supported Roblox method and use the intended Roblox account. This item is specific to Mining Simulator 2.', '/uploads/products/other-roblox-doggy-backpack-mining-simulator-2-dlc-official-website-key-global.jpg', 2, 304),
    ('rewup-rewup-paypal-10-eur-voucher-global', 'RewUp PayPal 10 EUR Voucher GLOBAL', 'This RewUp voucher has a face value of €10. It is intended for use through the RewUp redemption service in accordance with the voucher terms.

Check the payout currency and redemption steps before entering your code. Use the official RewUp service for the transaction.', '/uploads/products/rewup-rewup-paypal-10-eur-voucher-global.png', 6, 54),
    ('other-pubg-mobile-pin-600-60-uc-key-global', 'PUBG Mobile 600 + 60 UC (Unknown Cash) Key GLOBAL', 'This PUBG Mobile top-up contains 600 UC plus a 60 UC bonus. UC can go toward eligible items or passes available in the game.

Use the redemption details for the PUBG Mobile profile that should receive the currency. The code does not apply to the PC or console edition.', '/uploads/products/other-pubg-mobile-pin-600-60-uc-key-global.jpg', 5, 305),
    ('rockstar-social-club-rockstar-social-club-grand-theft-auto-v-premium-online-edition-rockstar-games-launcher-key-global', 'Grand Theft Auto V: Premium Online Edition Rockstar Games Launcher Key GLOBAL', 'Grand Theft Auto V Premium Online Edition includes the story of Michael, Franklin and Trevor, as well as access to GTA Online and the Criminal Enterprise Starter Pack.

This key activates through Rockstar Games Launcher on PC. Use it on the Rockstar account you intend to play with.', '/uploads/products/rockstar-social-club-rockstar-social-club-grand-theft-auto-v-premium-online-edition-rockstar-games-launcher-key-global.jpg', 1, 61),
    ('other-minecraft-experience-cape-dlc-pc-official-website-key-global', 'Minecraft Experience Cape (DLC) (PC) Official Website Key GLOBAL', 'The Experience Cape is a cosmetic item for a compatible Minecraft account on PC. It changes how your character looks without adding new gameplay features.

This code grants the cape only. Follow the official Minecraft redemption instructions and check the account and edition restrictions.', '/uploads/products/other-minecraft-experience-cape-dlc-pc-official-website-key-global.jpg', 2, 157),
    ('paypal-instant-top-up-1-usd-global', 'PayPal Instant Top Up 1 USD GLOBAL', 'This product represents a US$1 PayPal top-up through the service associated with the code. It is a small-value addition rather than a direct purchase from a PayPal merchant.

Review the redemption service''s account and payout conditions first. The balance is denominated in US dollars.', '/uploads/products/paypal-instant-top-up-1-usd-global.png', 6, 19),
    ('other-avast-premium-security-1-device-1-year-avast-key-global', 'Avast Premium Security 1 Device 1 Year Avast Key GLOBAL', 'Avast Premium Security provides one year of protection for one supported device. It is designed to help detect malicious files and threats encountered while browsing.

This single-device license is suited to protecting one main computer. Check which Avast edition and operating system are supported before activation.', '/uploads/products/other-avast-premium-security-1-device-1-year-avast-key-global.jpg', 7, 41),
    ('fortnite-fortnite-its-complicated-emote-dlc-epic-games-key-global', 'Fortnite - It''s Complicated Emote (DLC) Epic Games Key GLOBAL', 'It''s Complicated is a Fortnite emote for use on a linked Epic Games account. It adds a cosmetic animation and does not affect match performance.

Redeem the code using the Epic account tied to your Fortnite profile. The listing includes the named emote only.', '/uploads/products/fortnite-fortnite-its-complicated-emote-dlc-epic-games-key-global.jpg', 2, 3),
    ('aaseus-easeus-data-recovery-wizard-pro-2026-1-month-1-pc-key-global', 'EaseUS Data Recovery Wizard Pro 2026 (1 Month, 1 PC) Key GLOBAL', 'EaseUS Data Recovery Wizard Pro 2026 helps scan storage for deleted or lost files and recover those that are still readable. This listing covers one PC for one month.

When attempting recovery, avoid writing new files to the affected drive and save recovered files to another drive. The outcome depends on the condition of the original data.', '/uploads/products/aaseus-easeus-data-recovery-wizard-pro-2026-1-month-1-pc-key-global.png', 7, 107),
    ('other-call-of-duty-black-ops-6-15-min-double-xp-15-min-weapon-xp-dlc-ps4-ps5-xbox-one-xbox-series-x-pc-official-website-key-global', 'Call of Duty: Black Ops 6 - 15 Min Double XP + 15 Min Weapon XP (DLC) (PS4/PS5/XBOX ONE/XBOX SERIES X/PC) Official Website Key GLOBAL', 'This Black Ops 6 DLC includes 15 minutes of Double XP and 15 minutes of Double Weapon XP. The two boosts apply to different progression tracks.

The code is for players who already have the game and a compatible linked Call of Duty account. Review the redemption steps before using either timed boost.', '/uploads/products/other-call-of-duty-black-ops-6-15-min-double-xp-15-min-weapon-xp-dlc-ps4-ps5-xbox-one-xbox-series-x-pc-official-website-key-global.jpg', 2, 168),
    ('microsoft-windows-microsoft-windows-11-home-retail-key-clean-install-only-no-upgrade-global', 'Microsoft Windows 11 Home Key GLOBAL', 'Activate Windows 11 Home on a compatible PC. The Home edition is intended for everyday use such as web browsing, gaming and personal productivity.

Confirm that the computer meets the Windows 11 system requirements and that you are installing or activating the Home edition.', '/uploads/products/microsoft-windows-microsoft-windows-11-home-retail-key-clean-install-only-no-upgrade-global.png', 7, 224),
    ('nitro-pdf-nitro-pdf-pro-14-lifetime-key-global', 'Nitro PDF Pro 14 Lifetime Key GLOBAL', 'Nitro PDF Pro 14 is a desktop tool for editing, converting and organizing PDF documents. It can be used to combine files, make document changes and prepare PDFs for sharing.

This listing is for a lifetime key for version 14. Check the license terms before assuming it includes later major versions or online services.', '/uploads/products/nitro-pdf-nitro-pdf-pro-14-lifetime-key-global.png', 7, 306),
    ('adobe-adobe-creative-cloud-pro-1-month-subscription-key-global', 'Adobe Creative Cloud Pro 1 Month Subscription Key GLOBAL', 'Adobe Creative Cloud Pro provides a one-month subscription for creative work such as photo editing, illustration and video production. The available applications depend on the plan''s terms.

Use the Adobe account on which you want to activate the subscription. Check how the code applies if you already have an active Creative Cloud plan.', '/uploads/products/adobe-adobe-creative-cloud-pro-1-month-subscription-key-global.jpg', 7, 100),
    ('kaspersky-premium-1-year-5-devices-key-europe', 'Kaspersky Premium (1 Year / 5 Devices) Key EUROPE', 'Kaspersky Premium provides one year of security for up to five compatible devices. It is a practical option for a household with several computers and mobile devices.

Activate within the listed European region. Review device requirements before deciding which computers and phones to cover.', '/uploads/products/kaspersky-premium-1-year-5-devices-key-europe.jpg', 7, 28),
    ('steam-gift-card-steam-wallet-gift-card-10-eur-steam-key-lithuania', 'Steam Wallet Gift Card 10 EUR Steam Key LITHUANIA', 'Add €10 to an eligible Lithuanian Steam Wallet. The credit can be used for a small purchase or combined with funds already in the wallet.

This is a wallet code that you redeem on Steam. Check that the account''s store country supports this Lithuanian listing.', '/uploads/products/steam-gift-card-steam-wallet-gift-card-10-eur-steam-key-lithuania.jpg', 4, 8),
    ('razer-razer-gold-gift-card-40-usd-key-global', 'Razer Gold Gift Card 40 USD Key GLOBAL', 'This Razer Gold card adds US$40 of prepaid value to a compatible wallet. The balance can be used with participating games and digital services.

Check the account''s currency before redeeming and confirm that your intended merchant accepts Razer Gold.', '/uploads/products/razer-razer-gold-gift-card-40-usd-key-global.jpg', 3, 21),
    ('other-test-mobcharge', 'Test_MobCharge', 'This demo listing represents a mobile recharge in the test catalog. It can be used to exercise the product and checkout screens with a mobile top-up product type.

The listing is test data and should not be treated as a real phone credit offer. Use it only for checking the demo workflow.', '/uploads/products/other-test-mobcharge.jpg', 9, 4),
    ('steam-human-fall-flat-steam-key-global', 'Human: Fall Flat Steam Key GLOBAL', 'Human: Fall Flat is a physics-based puzzle game about moving through surreal levels with a deliberately clumsy character. Solve obstacles by climbing, dragging objects and experimenting with the environment.

Play on your own or work through puzzles with friends in supported multiplayer modes. This PC listing activates on Steam.', '/uploads/products/steam-human-fall-flat-steam-key-global.jpg', 1, 1),
    ('kaspersky-kaspersky-premium-1-year-3-devices-key-europe', 'Kaspersky Premium (1 Year / 3 Devices) Key EUROPE', 'Kaspersky Premium covers up to three supported devices for one year. It is useful for protecting a small group of personal devices with a single subscription.

This key is listed for Europe. Check system requirements and feature availability before assigning it to a computer or phone.', '/uploads/products/kaspersky-kaspersky-premium-1-year-3-devices-key-europe.jpg', 7, 28),
    ('airalo-airalo-esim-20-usd-voucher-global', 'Airalo eSIM 20 USD Voucher GLOBAL', 'This US$20 Airalo voucher can be used toward an eligible travel data plan. It is useful when you want to pick your destination and data allowance after receiving the voucher.

Choose an eSIM compatible with your phone and itinerary. Confirm the voucher currency and redemption conditions before buying a plan.', '/uploads/products/airalo-airalo-esim-20-usd-voucher-global.jpg', 11, 301),
    ('xbox-xbox-live-10-eur-xbox-live-key-europe', 'Xbox Live Gift Card 10 EUR Xbox Live Key EUROPE', 'Add €10 of credit to an eligible Microsoft account for purchases supported by Xbox. The balance can go toward games, downloadable content or other eligible store items.

This is a European Xbox gift card. Verify your account''s region and currency before redeeming the code.', '/uploads/products/xbox-xbox-live-10-eur-xbox-live-key-europe.jpg', 4, 2),
    ('steam-gift-terraria-steam-gift-global', 'Terraria Steam Gift GLOBAL', 'Terraria is a 2D sandbox where you mine, craft equipment, build bases and fight bosses. Exploration takes you from the surface into caves and other biomes with different resources and enemies.

This listing is delivered as a Steam Gift. Accept it on a compatible Steam account before installing the game.', '/uploads/products/steam-gift-terraria-steam-gift-global.jpg', 1, 43),
    ('novyro-novyro-esim-unlimited-33-countries-3-day-key-europe', 'Novyro eSIM Unlimited 33 Countries 3-Day Key EUROPE', 'This Novyro travel eSIM offers three days of unlimited data across the plan''s listed 33 countries. Its short duration fits a weekend trip or a brief stopover.

Check all covered destinations and read any fair-use or speed conditions before activation. Your device must support eSIM.', '/uploads/products/novyro-novyro-esim-unlimited-33-countries-3-day-key-europe.png', 11, 249),
    ('riot-games-valorant-gift-card-1000-valorant-points-europe', 'Valorant Points 1000 VP Key - EUROPE', 'This European VALORANT key adds 1,000 VP to an eligible account. Use the balance for available paid cosmetic items or save it toward a later purchase.

Confirm your Riot account''s region before entering the code. The listing includes VP only and does not specify an item from the shop.', '/uploads/products/riot-games-valorant-gift-card-1000-valorant-points-europe.jpg', 5, 7),
    ('roblox-roblox-card-10-usd-robux-key-global', 'Roblox Card 10 USD Robux Key GLOBAL', 'This Roblox card carries US$10 of value. Redeem it through Roblox and use the resulting credit according to the options available to your account.

Check the currency and redemption conditions in advance. The face value is in dollars rather than a fixed number of Robux.', '/uploads/products/roblox-roblox-card-10-usd-robux-key-global.jpg', 4, 13),
    ('transcash-transcash-20-eur-voucher-lithuania', 'Transcash 20 EUR Voucher LITHUANIA', 'Add €20 in prepaid value through an eligible Transcash service with this voucher. It is listed for Lithuania and intended for accounts that support the code.

Confirm the destination account and follow the service''s redemption instructions. Keep the voucher code private until you use it.', '/uploads/products/transcash-transcash-20-eur-voucher-lithuania.jpg', 6, 133),
    ('gigsky-gigsky-gift-card-5-eur-key-global', 'GigSky Gift Card 5 EUR Key GLOBAL', 'This €5 GigSky gift card can contribute toward an eligible travel data purchase. It is a small denomination that can be used when you choose your GigSky plan.

Check supported destinations and device requirements before applying the gift card. The credit itself does not provision an eSIM.', '/uploads/products/gigsky-gigsky-gift-card-5-eur-key-global.jpg', 11, 303),
    ('fortnite-fortnite-13500-v-bucks-gift-card-key-global', 'Fortnite - 13500 V-Bucks Gift Card Key GLOBAL', 'Add 13,500 V-Bucks to an eligible Fortnite account. The currency can be spent on available in-game items over multiple purchases.

Check the supported account and platform requirements before redemption. The code grants currency rather than particular outfits or passes.', '/uploads/products/fortnite-fortnite-13500-v-bucks-gift-card-key-global.jpg', 5, 65),
    ('paysafecard-paysafecard-50-eur-voucher-lithuania', 'PaysafeCard Classic 50 EUR Voucher LITHUANIA', 'This PaysafeCard Classic code has a face value of €50 and is listed for Lithuania. It can be used at merchants that support the prepaid payment method.

Confirm the merchant and account requirements before entering the code. Any payment limits are governed by PaysafeCard and the merchant.', '/uploads/products/paysafecard-paysafecard-50-eur-voucher-lithuania.png', 6, 46),
    ('flexepin-flexepin-10-eur-voucher-lithuania', 'Flexepin 10 EUR Voucher LITHUANIA', 'This €10 Flexepin voucher is a prepaid code for use with a merchant that accepts Flexepin. The smaller denomination is useful for a low-value eligible purchase.

Check that the merchant supports vouchers listed for Lithuania. Enter the code only on the intended merchant''s payment page.', '/uploads/products/flexepin-flexepin-10-eur-voucher-lithuania.jpg', 6, 38),
    ('other-pubg-mobile-pin-300-25-uc-key-global', 'PUBG Mobile 300 + 25 UC (Unknown Cash) Key GLOBAL', 'Receive 300 UC plus a 25 UC bonus for PUBG Mobile. Use this balance for eligible items offered through the mobile game''s shop.

Use the correct PUBG Mobile player details when redeeming. This listing does not include the base game or content for PUBG on other platforms.', '/uploads/products/other-pubg-mobile-pin-300-25-uc-key-global.jpg', 5, 305),
    ('rockstar-social-club-grand-theft-auto-v-enhanced-pc-rockstar-games-launcher-key-global', 'Grand Theft Auto V Enhanced (PC) Rockstar Games Launcher Key GLOBAL', 'Grand Theft Auto V Enhanced is the PC release with updated presentation and PC-specific enhancements. Explore Los Santos in the story campaign or join activities in GTA Online.

Activate this version through Rockstar Games Launcher. Check the enhanced edition''s PC requirements before installing.', '/uploads/products/rockstar-social-club-grand-theft-auto-v-enhanced-pc-rockstar-games-launcher-key-global.jpg', 1, 61),
    ('other-call-of-duty-modern-warfare-ii-jack-links-items-30-min-double-xp-dlc-official-website-key-global', 'Call of Duty: Modern Warfare II - Random Jack Link''s Item + 30 min Double XP (DLC) Official Website Key GLOBAL', 'This Modern Warfare II promo code includes one random Jack Link''s item and 30 minutes of Double XP. The cosmetic reward depends on the promotional code you receive.

The DLC requires the game and a linked Call of Duty account. Review the redemption instructions before using the timed XP boost.', '/uploads/products/other-call-of-duty-modern-warfare-ii-jack-links-items-30-min-double-xp-dlc-official-website-key-global.jpg', 2, 83),
    ('other-minecraft-home-cape-dlc-pc-official-website-key-global', 'Minecraft Home Cape (DLC) (PC) Official Website Key GLOBAL', 'The Home Cape is a Minecraft cosmetic for eligible PC players. Equipping it changes your character''s appearance in supported parts of the game.

This is an add-on for an existing Minecraft account. Check the official redemption and edition requirements before using the code.', '/uploads/products/other-minecraft-home-cape-dlc-pc-official-website-key-global.jpg', 2, 157),
    ('rewup-rewup-paypal-20-eur-voucher-global', 'RewUp PayPal 20 EUR Voucher GLOBAL', 'This €20 RewUp voucher can be redeemed through the service listed for the product. It represents a fixed value for an eligible RewUp transaction.

Review available payout options and any redemption restrictions before using it. Redeem through the official RewUp service.', '/uploads/products/rewup-rewup-paypal-20-eur-voucher-global.png', 6, 54),
    ('wondershare-wondershare-filmora-15-video-editor-1-device-lifetime-wondershare-key-pc-global', 'Wondershare Filmora 15 Video Editor (1 Device, Lifetime) Wondershare Key (PC) GLOBAL', 'Filmora 15 for PC lets you organize video clips, edit sound and add titles to a project timeline. It is suited to making presentations, tutorials and short videos.

This lifetime key is for one Windows device. Check which Filmora version, updates and optional assets the license covers.', '/uploads/products/wondershare-wondershare-filmora-15-video-editor-1-device-lifetime-wondershare-key-pc-global.png', 7, 97),
    ('psn-grand-theft-auto-vi-ps5-psn-key-europe', 'Grand Theft Auto VI (PS5) PSN Key EUROPE', 'Grand Theft Auto VI for PlayStation 5 takes the series back to Vice City and the surrounding state of Leonida. This listing is for the PS5 digital edition.

The key uses PlayStation Network and is listed for Europe. Check the region of your PSN account and the product''s release status before purchase.', '/uploads/products/psn-grand-theft-auto-vi-ps5-psn-key-europe.jpg', 1, 5),
    ('other-roblox-knife-crown-murder-mystery-2-dlc-official-website-key-global', 'Roblox: Knife Crown - Murder Mystery 2 (DLC) Official Website Key GLOBAL', 'The Knife Crown is an item for Murder Mystery 2 on Roblox. It is intended for players who want to add the named item to their collection in that experience.

Redeem using the method supplied for the key on the intended Roblox account. It does not add Robux to your balance.', '/uploads/products/other-roblox-knife-crown-murder-mystery-2-dlc-official-website-key-global.jpg', 2, 304),
    ('paypal-instant-top-up-1-eur-global', 'PayPal Instant Top Up 1 EUR GLOBAL', 'This PayPal top-up code represents €1 through the service listed on the product. It is a small euro-denominated amount intended for an eligible payout.

Check the provider''s redemption terms, including any account or currency requirements, before using the code.', '/uploads/products/paypal-instant-top-up-1-eur-global.png', 6, 19),
    ('other-antivirus-norton-360-for-gamers-50gb-3-devices-1-year-norton-key-europe', 'Antivírus Norton 360 for Gamers 50GB - 3 Devices 1 Year - Norton Key EUROPE', 'Norton 360 for Gamers provides one year of coverage for up to three supported devices. The listing includes 50 GB of cloud backup where that feature is available.

Check the European activation region and the operating systems supported by the subscription. Backup availability varies by device.', '/uploads/products/other-antivirus-norton-360-for-gamers-50gb-3-devices-1-year-norton-key-europe.jpg', 7, 57),
    ('other-f-secure-internet-security-1-user-1-year-key-global', 'F-Secure Internet Security 1 Device 1 Year Key GLOBAL', 'F-Secure Internet Security offers one year of coverage for one compatible device. It focuses on online protection for activities such as web browsing and shopping.

Install it on the device you intend to protect and verify compatibility first. This listing covers a single device.', '/uploads/products/other-f-secure-internet-security-1-user-1-year-key-global.jpg', 7, 103),
    ('aaseus-easeus-data-recovery-wizard-pro-2026-lifetime-1-pc-key-global', 'EaseUS Data Recovery Wizard Pro 2026 (Lifetime, 1 PC) Key GLOBAL', 'EaseUS Data Recovery Wizard Pro 2026 helps find and recover files from supported storage devices. This version comes with a lifetime license for one PC.

Recovery depends on whether the missing data is still present. Avoid writing new data to the affected drive and save recovered files elsewhere.', '/uploads/products/aaseus-easeus-data-recovery-wizard-pro-2026-lifetime-1-pc-key-global.png', 7, 107),
    ('razer-razer-gold-gift-card-35-usd-key-global', 'Razer Gold Gift Card 35 USD Key GLOBAL', 'Add US$35 to an eligible Razer Gold wallet. Use the balance for digital content from participating games and services.

Confirm the account''s currency and the merchant''s support for Razer Gold before trying to spend the credit.', '/uploads/products/razer-razer-gold-gift-card-35-usd-key-global.jpg', 3, 21),
    ('xbox-fortnite-minty-legends-pack-1000-v-bucks-xbox-live-key-global', 'Fortnite Minty Legends Pack + 1000 V-Bucks XBOX LIVE Key GLOBAL', 'Fortnite Minty Legends Pack combines mint-themed cosmetics with 1,000 V-Bucks. It is delivered as an Xbox Live key.

Redeem it using a compatible Xbox account connected to your Fortnite profile. The game is separate from the pack.', '/uploads/products/xbox-fortnite-minty-legends-pack-1000-v-bucks-xbox-live-key-global.jpg', 2, 2),
    ('steam-7-days-to-die-steam-key-global', '7 Days to Die Steam Key GLOBAL', '7 Days to Die combines crafting, exploration and base building in a zombie survival world. Gather supplies and reinforce your shelter before the next horde arrives.

This version activates on Steam. You can play alone or look for a server with rules that match how you want to survive.', '/uploads/products/steam-7-days-to-die-steam-key-global.jpg', 1, 1),
    ('steam-gift-card-steam-wallet-gift-card-30-eur-steam-key-lithuania', 'Steam Wallet Gift Card 30 EUR Steam Key LITHUANIA', 'This Steam Wallet gift card adds €30 to an eligible Lithuanian Steam account. Use it to buy games, DLC or other products that can be paid for with wallet credit.

Check the account''s store country before redeeming. The credit can be kept in the wallet until you are ready to spend it.', '/uploads/products/steam-gift-card-steam-wallet-gift-card-30-eur-steam-key-lithuania.jpg', 4, 8),
    ('airalo-airalo-esim-5-usd-voucher-global', 'Airalo eSIM 5 USD Voucher GLOBAL', 'This US$5 Airalo voucher provides a small amount of credit toward a compatible eSIM plan. It can help cover a short trip or part of a larger package.

Check that your destination is covered by the plan you choose and that your device supports eSIM. Voucher redemption and eSIM installation are separate steps.', '/uploads/products/airalo-airalo-esim-5-usd-voucher-global.jpg', 11, 301),
    ('razer-razer-gold-gift-card-60-usd-key-global', 'Razer Gold Gift Card 60 USD Key GLOBAL', 'This Razer Gold gift card provides US$60 in credit. It can fund eligible digital purchases at games and retailers that participate in the Razer Gold program.

Verify that the receiving wallet accepts US dollars and that the service you plan to use accepts Razer Gold.', '/uploads/products/razer-razer-gold-gift-card-60-usd-key-global.jpg', 3, 21),
    ('novyro-novyro-esim-3gb-7-day-33-countries-key-europe', 'Novyro eSIM 3GB 7-Day 33 Countries Key EUROPE', 'This Novyro package includes 3 GB of mobile data valid for seven days across the listed 33 countries. It suits light travel use such as maps, messages and occasional browsing.

Check the destination list and device compatibility before travelling. Review when the seven-day period begins in the activation instructions.', '/uploads/products/novyro-novyro-esim-3gb-7-day-33-countries-key-europe.png', 11, 249),
    ('riot-games-league-of-legends-gift-card-1240-rp-riot-key-europe', 'League of Legends Gift Card - 1240 RP - Riot Key EUROPE', 'Add 1,240 Riot Points to an eligible European League of Legends account. RP can be used for available items such as skins in the game''s store.

Check your account''s region before redeeming. This code grants the stated points balance rather than a particular skin.', '/uploads/products/riot-games-league-of-legends-gift-card-1240-rp-riot-key-europe.jpg', 5, 7),
    ('gigsky-gigsky-gift-card-25-eur-key-global', 'GigSky Gift Card 25 EUR Key GLOBAL', 'This €25 GigSky gift card provides credit toward eligible mobile data products. The recipient can choose a plan that fits the destination and expected data use.

Redeem under GigSky''s gift card conditions and confirm that the device used for the trip supports eSIM.', '/uploads/products/gigsky-gigsky-gift-card-25-eur-key-global.jpg', 11, 303),
    ('roblox-roblox-200-robux-key-global', 'Roblox - 200 Robux Key GLOBAL', 'This digital code adds 200 Robux to an eligible Roblox account. Spend the currency on available avatar items or purchases supported by the experiences you play.

Use the intended account when redeeming. Robux are an account balance rather than a specific virtual item.', '/uploads/products/roblox-roblox-200-robux-key-global.jpg', 5, 13),
    ('transcash-transcash-100-eur-voucher-lithuania', 'Transcash 100 EUR Voucher LITHUANIA', 'This Transcash voucher provides €100 in prepaid value for an eligible Transcash account. It is listed for Lithuania.

Check the voucher''s redemption requirements and use official Transcash channels. Do not share the code with anyone who should not have access to the balance.', '/uploads/products/transcash-transcash-100-eur-voucher-lithuania.jpg', 6, 133),
    ('rockstar-social-club-red-dead-redemption-2-pc-rockstar-key-global', 'Red Dead Redemption 2 PC Rockstar Key GLOBAL', 'Red Dead Redemption 2 follows Arthur Morgan and the Van der Linde gang as they travel through the late American frontier. Alongside the story you can explore towns and wilderness, hunt and help your camp.

This PC key activates on Rockstar Games Launcher. Check storage and system requirements before downloading.', '/uploads/products/rockstar-social-club-red-dead-redemption-2-pc-rockstar-key-global.jpg', 1, 61),
    ('paysafecard-paysafecard-10-eur-voucher-lithuania', 'PaysafeCard Classic 10 EUR Voucher LITHUANIA', 'This €10 PaysafeCard Classic voucher represents prepaid value for supported online payments. It is listed for use under the Lithuanian offer conditions.

Check that the recipient merchant accepts PaysafeCard and that your account is eligible before applying the code.', '/uploads/products/paysafecard-paysafecard-10-eur-voucher-lithuania.png', 6, 46),
    ('fortnite-fortnite-2800-v-bucks-gift-card-key-global', 'Fortnite - 2800 V-Bucks Gift Card Key GLOBAL', 'Add 2,800 V-Bucks to an eligible Fortnite account. Use the currency on available in-game items or keep some of the balance for a future shop rotation.

Review the redemption instructions for the platform you play on. The card includes currency only.', '/uploads/products/fortnite-fortnite-2800-v-bucks-gift-card-key-global.jpg', 5, 65),
    ('flexepin-flexepin-20-eur-voucher-lithuania', 'Flexepin 20 EUR Voucher LITHUANIA', 'This €20 Flexepin voucher provides a fixed prepaid payment amount at supported merchants. The listing is for Lithuania.

Confirm merchant acceptance and redemption requirements before revealing the code. Use it only on the intended payment page.', '/uploads/products/flexepin-flexepin-20-eur-voucher-lithuania.jpg', 6, 38),
    ('other-pubg-mobile-60-uc-unknown-cash-key-global', 'PUBG Mobile 60 UC (Unknown Cash) Key GLOBAL', 'This PUBG Mobile code adds 60 UC to a compatible profile. It is a small top-up for players who need additional currency for eligible in-game purchases.

Use the supported redemption steps with your PUBG Mobile account details. The offer is for the mobile game.', '/uploads/products/other-pubg-mobile-60-uc-unknown-cash-key-global.jpg', 5, 305),
    ('other-call-of-duty-modern-warfare-4-1-hour-double-xp-1-hour-double-weapon-xp-dlc-ps4-ps5-xbox-one-xbox-series-x-pc-official-website-key-global', 'Call of Duty: Modern Warfare 4 - 1 HOUR DOUBLE XP + 1 HOUR DOUBLE WEAPON XP (DLC) (PS4/PS5/XBOX ONE/XBOX SERIES X/PC) Official Website Key GLOBAL', 'This Modern Warfare 4 add-on gives you one hour of Double XP and one hour of Double Weapon XP. Each token boosts its corresponding progress track for the stated duration.

You need the base game and a compatible Call of Duty account. Check the redemption instructions before activating the tokens.', '/uploads/products/other-call-of-duty-modern-warfare-4-1-hour-double-xp-1-hour-double-weapon-xp-dlc-ps4-ps5-xbox-one-xbox-series-x-pc-official-website-key-global.png', 2, 4),
    ('psn-call-of-duty-modern-warfare-iii-ps5-psn-key-europe', 'Call of Duty: Modern Warfare III (PS5) PSN Key EUROPE', 'Modern Warfare III for PS5 offers a Call of Duty campaign and multiplayer combat with different maps and modes. This listing is for the PlayStation digital key.

Redeem the European PSN key using a compatible account and check which components need to be installed for the modes you plan to play.', '/uploads/products/psn-call-of-duty-modern-warfare-iii-ps5-psn-key-europe.jpg', 1, 5),
    ('minecraft-minecraft-builder-cape-dlc-pc-official-website-key-global', 'Minecraft Builder Cape (DLC) (PC) Official Website Key GLOBAL', 'The Builder Cape is a Minecraft cosmetic for eligible players on PC. It lets you change your character''s appearance while you build or explore.

This listing grants the cape only. Check the official account and edition requirements before redeeming.', '/uploads/products/minecraft-minecraft-builder-cape-dlc-pc-official-website-key-global.png', 2, 157),
    ('other-norton-360-deluxe-25gb-3-devices-1-year-norton-key-europe', 'Norton 360 Deluxe 25GB - 3 Devices 1 Year - Norton Key EUROPE', 'Norton 360 Deluxe offers one year of security for up to three supported devices. The listing includes 25 GB of cloud backup where supported.

This key is listed for Europe. Review the supported devices and operating systems before activation.', '/uploads/products/other-norton-360-deluxe-25gb-3-devices-1-year-norton-key-europe.jpg', 7, 57),
    ('wondershare-wondershare-filmora-15-advanced-annual-plan-windows-1-device-1-year-key-global', 'Wondershare Filmora 15 Advanced Annual Plan (Windows) 1 Device, 1 Year Key GLOBAL', 'Filmora 15 Advanced is a Windows video editor for cutting footage, arranging sound and adding effects. This annual plan covers one Windows device for one year.

Activate the subscription on the Wondershare account you plan to use for your projects. Check the plan for included effects and other optional features.', '/uploads/products/wondershare-wondershare-filmora-15-advanced-annual-plan-windows-1-device-1-year-key-global.png', 7, 97),
    ('other-f-secure-internet-security-3-devices-1-year-key-global', 'F-Secure Internet Security 3 Devices 1 Year Key GLOBAL', 'F-Secure Internet Security covers up to three compatible devices for one year. It is suited to households that want to protect everyday browsing and downloads on several devices.

Verify that each device is supported before installing. Features can vary between desktop and mobile systems.', '/uploads/products/other-f-secure-internet-security-3-devices-1-year-key-global.jpg', 7, 103),
    ('aaseus-easeus-data-recovery-wizard-professional-2025-lifetime-upgrade-1-device-1-month-key-global', 'EaseUs Data Recovery Wizard Professional 2025 Lifetime Upgrade - 1 Device 1 Month Key GLOBAL', 'This EaseUS Data Recovery Wizard Professional 2025 listing is for one device. The software scans compatible drives for lost files that may still be recoverable.

The offer title mentions both a lifetime upgrade and one month. Check the seller''s activation terms to confirm the license period and upgrade eligibility before purchase.', '/uploads/products/aaseus-easeus-data-recovery-wizard-professional-2025-lifetime-upgrade-1-device-1-month-key-global.png', 7, 107),
    ('steam-gift-card-steam-wallet-gift-card-100-eur-steam-key-lithuania', 'Steam Wallet Gift Card 100 EUR Steam Key LITHUANIA', 'This Steam Wallet gift card adds €100 of credit to an eligible Lithuanian account. It can cover a larger purchase or be spent on several eligible products over time.

Confirm that the receiving Steam account supports Lithuanian redemption. This item adds credit to the wallet and can be redeemed on Steam.', '/uploads/products/steam-gift-card-steam-wallet-gift-card-100-eur-steam-key-lithuania.jpg', 4, 8),
    ('razer-razer-gold-gift-card-4-usd-key-global', 'Razer Gold Gift Card 4 USD Key GLOBAL', 'This US$4 Razer Gold card provides prepaid credit for an eligible wallet. It is useful as a small add-on to an existing balance.

Check that the account accepts US dollars and that the service where you intend to make a purchase supports Razer Gold.', '/uploads/products/razer-razer-gold-gift-card-4-usd-key-global.jpg', 3, 21),
    ('xbox-xbox-live-25-eur-xbox-live-key-europe', 'Xbox Live Gift Card 25 EUR Xbox Live Key EUROPE', 'Add €25 of store credit to an eligible European Microsoft account. Spend the balance on supported Xbox purchases such as games and add-ons.

This gift card adds a balance instead of starting a subscription. Verify the region and currency of the receiving account before activating it.', '/uploads/products/xbox-xbox-live-25-eur-xbox-live-key-europe.jpg', 4, 2),
    ('airalo-airalo-esim-10-usd-voucher-global', 'Airalo eSIM 10 USD Voucher GLOBAL', 'This Airalo voucher provides US$10 toward an eligible travel eSIM plan. Use it after choosing a region and data allowance that suit your itinerary.

Check coverage and confirm that your phone is unlocked and supports eSIM. Plan activation follows the instructions for the eSIM you buy.', '/uploads/products/airalo-airalo-esim-10-usd-voucher-global.jpg', 11, 301),
    ('novyro-novyro-esim-unlimited-3-day-33-countries-key-europe', 'Novyro eSIM Unlimited 3-Day 33 Countries Key EUROPE', 'Stay connected on a short trip with this three-day Novyro unlimited eSIM. The plan covers the listed 33 European destinations and is intended for compatible eSIM devices.

Read the coverage and fair-use terms before travelling. Follow the activation instructions so the three-day window starts when you need it.', '/uploads/products/novyro-novyro-esim-unlimited-3-day-33-countries-key-europe.png', 11, 249),
    ('steam-elden-ring-shadow-of-the-erdtree-dlc-pc-steam-key-europe', 'ELDEN RING Shadow of the Erdtree (DLC) (PC) Steam Key EUROPE', 'Shadow of the Erdtree expands Elden Ring with the Realm of Shadow, new enemies and equipment. It adds a separate area to explore alongside the base game''s world.

The PC expansion requires Elden Ring on Steam. Check compatibility with your base game before redeeming this European key.', '/uploads/products/steam-elden-ring-shadow-of-the-erdtree-dlc-pc-steam-key-europe.jpg', 2, 1),
    ('rockstar-social-club-grand-theft-auto-v-gta-rockstar-social-club-key-global', 'Grand Theft Auto V Rockstar Games Launcher Key GLOBAL', 'Grand Theft Auto V follows three criminals whose stories cross in Los Santos. The open world offers missions, driving and a range of optional activities outside the main story.

This PC key activates through Rockstar Games Launcher. Check the system requirements for the edition listed before installing.', '/uploads/products/rockstar-social-club-grand-theft-auto-v-gta-rockstar-social-club-key-global.jpg', 1, 61),
    ('paysafecard-paysafecard-100-eur-voucher-lithuania', 'PaysafeCard Classic 100 EUR Voucher LITHUANIA', 'This PaysafeCard Classic voucher contains €100 in prepaid value for compatible merchants. It is listed for Lithuania and intended as a prepaid payment code.

Confirm that the merchant supports PaysafeCard and accepts this denomination and region before redemption. Keep the code private until payment.', '/uploads/products/paysafecard-paysafecard-100-eur-voucher-lithuania.png', 6, 46);

