INSERT INTO products (slug, name, description, cover_image_url, product_type_id, platform_id)
SELECT seed.slug, seed.name, seed.description, '/uploads/products/home-' || seed.art || '.jpg', pt.id, pl.id
FROM (VALUES
    ('apple-apple-itunes-gift-card-10-usd-itunes-key-united-states', 'Apple iTunes Gift Card 10 USD iTunes Key UNITED STATES', 'Adds USD 10 to the balance of a US Apple Account. The balance can be used for eligible purchases in Apple digital stores.' || E'\n\n' || 'Redeem the code while signed in to an account registered in the United States. The credit is denominated in US dollars.', 'apple', 'top-up', 'apple'),
    ('amazon-amazon-gift-card-10-usd-united-states', 'Amazon Gift Card 10 USD UNITED STATES', 'This gift card adds USD 10 to an Amazon.com gift card balance for eligible purchases.' || E'\n\n' || 'Apply the code to a US Amazon.com account before checkout. The balance is tied to the US storefront.', 'amazon', 'top-up', 'amazon'),
    ('spotify-spotify-gift-card-10-usd-key-united-states', 'Spotify Gift Card 10 USD Key UNITED STATES', 'This USD 10 voucher can be applied to an eligible Spotify Premium account in the United States.' || E'\n\n' || 'Check the account country and plan before redeeming. Eligibility depends on the subscription type and region.', 'spotify', 'top-up', 'spotify'),
    ('binance-binance-gift-card-usdt-45-5-usd-key-global', 'Binance Gift Card (USDT) 45.5 USD Key GLOBAL', 'This Binance voucher is denominated in USDT. Redeeming the code applies the stated credit to an eligible Binance account.' || E'\n\n' || 'Check that Binance and gift card redemption are available for your account and location before using the code.', 'binance', 'top-up', 'binance'),
    ('xbox-ea-sports-fc-26-1050-fc-points-xbox-live-key-global', 'EA Sports FC 26 - 1050 FC Points XBOX LIVE Key GLOBAL', 'Adds 1050 FC Points to the Xbox edition of EA Sports FC 26. You can spend them on eligible in-game content.' || E'\n\n' || 'This is in-game currency and requires the base game on a compatible Xbox account.', 'fifa', 'game-points', 'xbox'),
    ('steam-age-of-empires-ii-definitive-edition-steam-key-global', 'Age of Empires II: Definitive Edition Steam Key GLOBAL', 'Build a settlement, gather resources, and command armies through historical campaigns in this real-time strategy game.' || E'\n\n' || 'The Definitive Edition remasters the original visuals and supports skirmishes and multiplayer on Steam.', 'strategy', 'game', 'steam'),
    ('steam-stardew-valley-steam-key-global', 'Stardew Valley Steam Key GLOBAL', 'Restore an inherited farm in Pelican Town by growing crops, raising animals, and building relationships with your neighbors.' || E'\n\n' || 'Explore mines, fish, or take part in seasonal festivals at your own pace. This edition activates on Steam.', 'indie', 'game', 'steam'),
    ('xbox-grand-theft-auto-vi-xbox-series-x-s-xbox-live-key-global', 'Grand Theft Auto VI (Xbox Series X|S) XBOX LIVE Key GLOBAL', 'Explore Vice City and the state of Leonida in the Xbox Series X|S edition of Grand Theft Auto VI.' || E'\n\n' || 'This listing is for the Xbox Series X|S version. Check release and activation availability before purchase.', 'preorder', 'game', 'xbox'),
    ('nintendo-nintendo-eshop-card-10-eur-key-germany', 'Nintendo eShop Card 10 EUR Key GERMANY', 'Add EUR 10 to an eligible German Nintendo Account for digital purchases on Nintendo eShop.' || E'\n\n' || 'Redeem the code on an account set to Germany. Check your account region before applying the credit.', 'nintendo', 'giftcard', 'nintendo'),
    ('psn-playstation-network-card-10-usd-usa-psn-key-united-states', 'PlayStation Network Card 10 USD (USA) PSN Key UNITED STATES', 'Adds USD 10 to the wallet of a US PlayStation Network account for purchases on PlayStation Store.' || E'\n\n' || 'Redeem this code on the US storefront. The wallet currency and account country must match the card.', 'psn', 'giftcard', 'psn')
) AS seed(slug, name, description, art, type_slug, platform_slug)
JOIN product_types pt ON pt.slug = seed.type_slug
JOIN platforms pl ON pl.slug = seed.platform_slug
ON CONFLICT (slug) DO NOTHING;

INSERT INTO product_regions (product_id, region_id)
SELECT p.id, r.id
FROM products p
JOIN regions r ON r.slug = CASE
    WHEN p.cover_image_url IN ('/uploads/products/home-apple.jpg', '/uploads/products/home-amazon.jpg', '/uploads/products/home-spotify.jpg', '/uploads/products/home-psn.jpg') THEN 'united-states'
    WHEN p.cover_image_url = '/uploads/products/home-nintendo.jpg' THEN 'germany'
    ELSE 'global'
END
WHERE p.cover_image_url LIKE '/uploads/products/home-%.jpg'
ON CONFLICT DO NOTHING;

INSERT INTO product_countries (product_id, country_code)
SELECT p.id, c.code
FROM products p
JOIN product_regions pr ON pr.product_id = p.id
JOIN regions r ON r.id = pr.region_id
JOIN countries c ON r.slug = 'global' OR (r.slug = 'united-states' AND c.code = 'US') OR (r.slug = 'germany' AND c.code = 'DE')
WHERE p.cover_image_url LIKE '/uploads/products/home-%.jpg'
ON CONFLICT DO NOTHING;

INSERT INTO product_genres (product_id, genre_id)
SELECT p.id, g.id
FROM (VALUES
    ('strategy', 'strategy-games'),
    ('indie', 'indie-games'),
    ('indie', 'simulation-games'),
    ('indie', 'rpg-games'),
    ('preorder', 'action-games'),
    ('preorder', 'adventure-games')
) AS seed(art, genre_slug)
JOIN products p ON p.cover_image_url = '/uploads/products/home-' || seed.art || '.jpg'
JOIN genres g ON g.slug = seed.genre_slug
ON CONFLICT DO NOTHING;

INSERT INTO product_operating_systems (product_id, operating_system_id)
SELECT p.id, os.id
FROM products p
JOIN operating_systems os ON os.slug = 'windows'
WHERE p.cover_image_url IN ('/uploads/products/home-strategy.jpg', '/uploads/products/home-indie.jpg')
ON CONFLICT DO NOTHING;

