INSERT INTO products (slug, name, description, cover_image_url, product_type_id, platform_id)
SELECT seed.slug, seed.name, seed.description, '/uploads/products/home-' || seed.art || '.jpg', pt.id, pl.id
FROM seed_home_gift_cards seed
JOIN product_types pt ON pt.slug = 'top-up'
JOIN platforms pl ON pl.slug = seed.platform_slug
ON CONFLICT (slug) DO NOTHING;

INSERT INTO product_regions (product_id, region_id)
SELECT p.id, r.id FROM seed_home_gift_cards seed
JOIN products p ON p.slug = seed.slug
JOIN regions r ON r.slug = seed.region_slug
ON CONFLICT DO NOTHING;

INSERT INTO product_countries (product_id, country_code)
SELECT p.id, c.code FROM seed_home_gift_cards seed
JOIN products p ON p.slug = seed.slug
JOIN countries c ON seed.region_slug = 'global'
    OR (seed.region_slug = 'lithuania' AND c.code = 'LT')
    OR (seed.region_slug = 'france' AND c.code = 'FR')
ON CONFLICT DO NOTHING;

DROP TABLE seed_home_gift_cards;

